import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;

enum SeatStatus { AVAILABLE, HELD, BOOKED }
enum BookingStatus { PENDING, CONFIRMED, CANCELLED, EXPIRED }

class Seat {
    final String id; final String tier; final int price;
    SeatStatus status = SeatStatus.AVAILABLE;
    String holderId; long expiresAt;
    Seat(String id, String tier, int price) { this.id = id; this.tier = tier; this.price = price; }
}

class Show {
    final String id;
    final Map<String, Seat> seats = new HashMap<>();
    final ReentrantLock lock = new ReentrantLock();
    final Map<String, Hold> holds = new HashMap<>(); // holdId -> Hold
    Show(String id) { this.id = id; }
}

class Hold {
    final String holdId; final String showId; final String userId;
    final List<String> seatIds; final long expiresAt;
    Hold(String h, String s, String u, List<String> seats, long e) {
        holdId = h; showId = s; userId = u; seatIds = seats; expiresAt = e;
    }
}

class Booking {
    final String bookingId; final String holdId; final String userId;
    final List<String> seatIds; volatile BookingStatus status;
    Booking(String b, String h, String u, List<String> s) {
        bookingId = b; holdId = h; userId = u; seatIds = s; status = BookingStatus.PENDING;
    }
}

public class BookingService {
    private final Map<String, Show> shows = new ConcurrentHashMap<>();
    private final Map<String, Booking> bookingsByHold = new ConcurrentHashMap<>();
    private final ScheduledExecutorService sweeper = Executors.newSingleThreadScheduledExecutor();
    private final long HOLD_TTL_MS = 7 * 60 * 1000;

    public BookingService() {
        sweeper.scheduleAtFixedRate(this::sweepExpired, 30, 30, TimeUnit.SECONDS);
    }

    public Hold holdSeats(String userId, String showId, List<String> seatIds) throws Exception {
        Show show = Objects.requireNonNull(shows.get(showId), "no show");
        // TRADE-OFF: per-show lock serializes contenders for one show only.
        // Cross-show parallelism is unaffected,unlike a global synchronized method.
        if (!show.lock.tryLock(2, TimeUnit.SECONDS)) throw new Exception("show busy, retry");
        try {
            for (String sid : seatIds) {
                Seat st = show.seats.get(sid);
                if (st == null || st.status != SeatStatus.AVAILABLE) return null;
                if (st.status == SeatStatus.HELD && st.expiresAt > System.currentTimeMillis()) return null;
            }
            String holdId = UUID.randomUUID().toString();
            long exp = System.currentTimeMillis() + HOLD_TTL_MS;
            for (String sid : seatIds) {
                Seat st = show.seats.get(sid);
                st.status = SeatStatus.HELD; st.holderId = holdId; st.expiresAt = exp;
            }
            Hold h = new Hold(holdId, showId, userId, List.copyOf(seatIds), exp);
            show.holds.put(holdId, h);
            return h;
        } finally { show.lock.unlock(); }
    }

    public Booking confirm(String holdId, String userId) throws Exception {
        // Idempotent: second call with same holdId returns same booking.
        Booking existing = bookingsByHold.get(holdId);
        if (existing != null) return existing;
        // Find hold: linear scan is fine for LLD; index by holdId in prod.
        Hold target = null; Show owner = null;
        for (Show s : shows.values()) { Hold h = s.holds.get(holdId); if (h != null) { target = h; owner = s; break; } }
        if (target == null || !target.userId.equals(userId)) throw new Exception("invalid hold");
        if (target.expiresAt < System.currentTimeMillis()) { releaseHold(target, owner); throw new Exception("hold expired"); }
        // Payment verification happens OUTSIDE the lock in real code. Mocked here.
        owner.lock.lock();
        try {
            for (String sid : target.seatIds) {
                Seat st = owner.seats.get(sid);
                if (st.status != SeatStatus.HELD || !holdId.equals(st.holderId)) throw new Exception("seat stolen");
            }
            for (String sid : target.seatIds) owner.seats.get(sid).status = SeatStatus.BOOKED;
            Booking b = new Booking(UUID.randomUUID().toString(), holdId, userId, target.seatIds);
            b.status = BookingStatus.CONFIRMED;
            bookingsByHold.putIfAbsent(holdId, b);
            return bookingsByHold.get(holdId);
        } finally { owner.lock.unlock(); }
    }

    private void releaseHold(Hold h, Show s) {
        s.lock.lock();
        try { for (String sid : h.seatIds) { Seat st = s.seats.get(sid); if (st != null && h.holdId.equals(st.holderId) && st.status == SeatStatus.HELD) { st.status = SeatStatus.AVAILABLE; st.holderId = null; } } s.holds.remove(h.holdId); }
        finally { s.lock.unlock(); }
    }

    private void sweepExpired() {
        long now = System.currentTimeMillis();
        for (Show s : shows.values()) {
            List<Hold> dead = new ArrayList<>();
            s.lock.lock();
            try { for (Hold h : s.holds.values()) if (h.expiresAt < now && !bookingsByHold.containsKey(h.holdId)) dead.add(h); }
            finally { s.lock.unlock(); }
            for (Hold h : dead) releaseHold(h, s); // release re-locks briefly; never holds lock while looping
        }
    }
}

import threading, time, uuid

class Show:
    def __init__(self, sid, seat_ids):
        self.id = sid
        self.lock = threading.Lock()  # per-show: contention isolated per show
        self.seats = {s: ("AVAILABLE", None, 0) for s in seat_ids}  # status, holder, expiry
        self.holds = {}

class BookingService:
    TTL = 420  # 7 minutes
    def __init__(self):
        self.shows = {}
        self.bookings = {}  # hold_id -> booking

    def hold(self, user, show_id, wanted):
        sh = self.shows[show_id]
        # TRADE-OFF: blocking lock here is fair and simple.
        # tryLock+retry is friendlier under thundering herd for a hot premiere.
        with sh.lock:
            now = time.time()
            for s in wanted:
                st, holder, exp = sh.seats[s]
                if st == "BOOKED": return None
                if st == "HELD" and exp > now: return None
            hid = str(uuid.uuid4())
            exp = now + self.TTL
            for s in wanted:
                sh.seats[s] = ("HELD", hid, exp)
            sh.holds[hid] = (user, list(wanted), exp)
            return hid

    def confirm(self, user, hold_id, show_id):
        if hold_id in self.bookings:  # idempotent retry
            return self.bookings[hold_id]
        sh = self.shows[show_id]
        with sh.lock:
            rec = sh.holds.get(hold_id)
            if not rec or rec[0] != user: raise Exception("bad hold")
            _, wanted, exp = rec
            if exp < time.time(): raise Exception("expired")
            for s in wanted:
                st, holder, _ = sh.seats[s]
                if st != "HELD" or holder != hold_id: raise Exception("stolen")
            for s in wanted:
                _, _, _ = sh.seats[s]
                sh.seats[s] = ("BOOKED", hold_id, 0)
            self.bookings[hold_id] = (user, wanted)
            return self.bookings[hold_id]
